def gen(rng):
    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, a))

    tests = [
        fmt([10]), fmt([4, 9]), fmt([9, 4]), fmt([5, 5, 5, 5]), fmt([8, 6, 5, 3, 1]),
        fmt([1, 2, 3, 4, 5]), fmt([9, 4, 6, 2, 8, 5, 7]), fmt([10, 1, 9, 2, 3]), fmt([6, 1, 6, 10**6, 1]),
        fmt([10**6, 1]), fmt([1, 10**6]),
    ]
    for n in (3, 5, 8, 12, 20, 40):
        for hi in (10, 1000):
            tests.append(fmt([rng.randint(1, hi) for _ in range(n)]))
    big_start = len(tests)
    N = 10**5
    tests.append(fmt([rng.randint(1, 10**6) for _ in range(N)]))
    tests.append(fmt([1 + i * 10 for i in range(N)]))
    tests.append(fmt([10**6 - i * 10 for i in range(N)]))
    tests.append(fmt([10**6 - i for i in range(N // 2)] + [1 + i for i in range(N // 2)]))
    tests.append(fmt([rng.randint(500000, 500010) for _ in range(N)]))
    return tests[:6] + tests[big_start:] + tests[6:big_start]

